{"implementation": "def solve(case):
    tokens = case['tokens']
    calls = case['calls']
    sorted_calls = sorted(calls, key=lambda c: c['score'], reverse=True)
    selected = []
    for call in sorted_calls:
        overlap = False
        for sel in selected:
            if call['start'] < sel['end'] and call['end'] > sel['start']:
                overlap = True
                break
        if not overlap:
            selected.append(call)
    selected.sort(key=lambda c: c['start'], reverse=True)
    result_tokens = list(tokens)
    for call in selected:
        result_tokens = result_tokens[:call['start']] + call['replacement_tokens'] + result_tokens[call['end']:]
    selected_ids = [c['call_id'] for c in sorted(selected, key=lambda c: c['start'])]
    return {"selected_call_ids": selected_ids, "tokens": result_tokens}"}
